     1|/**
     2| * IVX Autonomous Dashboard — live W1–W12 job ledger (owner-only).
     3| *
     4| * Reads REAL production data from:
     5| *   GET https://api.ivxholding.com/api/ivx/autonomous/ledger
     6| *
     7| * No seed data: every job shown carries a stable job ID, status history with
     8| * timestamps, evidence, and blockers straight from the durable backend ledger.
     9| * Auto-refreshes via controlled polling (30s) + pull-to-refresh.
    10| */
    11|import React, { useState, useCallback, useEffect, useRef } from 'react';
    12|import {
    13|  View,
    14|  Text,
    15|  StyleSheet,
    16|  ScrollView,
    17|  TouchableOpacity,
    18|  ActivityIndicator,
    19|  RefreshControl,
    20|} from 'react-native';
    21|import { SafeAreaView } from 'react-native-safe-area-context';
    22|import { Stack, useRouter } from 'expo-router';
    23|import {
    24|  Activity,
    25|  AlertTriangle,
    26|  ArrowLeft,
    27|  CheckCircle2,
    28|  ChevronDown,
    29|  ChevronRight,
    30|  Clock,
    31|  Cpu,
    32|  ListChecks,
    33|  Lock,
    34|  RefreshCw,
    35|  ShieldCheck,
    36|} from 'lucide-react-native';
    37|import { getIVXAccessToken } from '@/lib/ivx-supabase-client';
    38|
    39|const API_BASE = (process.env.EXPO_PUBLIC_IVX_API_BASE_URL || 'https://api.ivxholding.com').replace(/\/+$/, '');
    40|const LEDGER_URL = `${API_BASE}/api/ivx/autonomous/ledger`;
    41|const GUARDIAN_URL = `${API_BASE}/api/ivx/autonomous/auth-guardian`;
    42|const QA_URL = `${API_BASE}/api/ivx/autonomous/qa`;
    43|const CREDENTIALS_URL = `${API_BASE}/api/ivx/autonomous/credentials`;
    44|const POLL_INTERVAL_MS = 30_000;
    45|
    46|type LedgerWorker = { id: string; name: string; scope: string };
    47|
    48|type LedgerHistoryEntry = { at: string; from: string | null; to: string; note: string | null };
    49|
    50|type LedgerJob = {
    51|  jobId: string;
    52|  workerId: string;
    53|  title: string;
    54|  status: string;
    55|  priority: string;
    56|  evidence: string | null;
    57|  blocker: string | null;
    58|  createdAt: string;
    59|  updatedAt: string;
    60|  history: LedgerHistoryEntry[];
    61|};
    62|
    63|type LedgerApproval = {
    64|  approvalId: string;
    65|  workerId: string;
    66|  title: string;
    67|  risk: string;
    68|  rollback: string;
    69|  status: string;
    70|  createdAt: string;
    71|};
    72|
    73|type LedgerCounts = {
    74|  workers: number;
    75|  jobs: number;
    76|  verified: number;
    77|  running: number;
    78|  blocked: number;
    79|  ownerActionRequired: number;
    80|  queued: number;
    81|  pendingApprovals: number;
    82|};
    83|
    84|type GuardianProbe = {
    85|  id: string;
    86|  name: string;
    87|  target: string;
    88|  ok: boolean;
    89|  httpStatus: number | null;
    90|  latencyMs: number;
    91|  detail: string;
    92|  checkedAt: string;
    93|};
    94|
    95|type GuardianIncident = {
    96|  incidentId: string;
    97|  probeId: string;
    98|  openedAt: string;
    99|  closedAt: string | null;
   100|  status: string;
   101|  detail: string;
   102|};
   103|
   104|type GuardianAlert = {
   105|  alertId: string;
   106|  severity: string;
   107|  area: string;
   108|  problem: string;
   109|  smsStatus: string;
   110|  messageId: string | null;
   111|  toMasked: string;
   112|  sentAt: string;
   113|  test: boolean;
   114|};
   115|
   116|type GuardianSmsProvider = {
   117|  provider?: string;
   118|  awsCredentialsConfigured?: boolean;
   119|  awsRegion?: string;
   120|  ownerPhoneResolved?: boolean;
   121|  ownerPhoneMasked?: string | null;
   122|  phoneSource?: string;
   123|  ready?: boolean;
   124|};
   125|
   126|type GuardianResponse = {
   127|  ok: boolean;
   128|  error?: string;
   129|  marker?: string;
   130|  generatedAt?: string;
   131|  totalRuns?: number;
   132|  overall?: string;
   133|  probes?: GuardianProbe[];
   134|  openIncidents?: GuardianIncident[];
   135|  recentIncidents?: GuardianIncident[];
   136|  smsProvider?: GuardianSmsProvider;
   137|  recentAlerts?: GuardianAlert[];
   138|};
   139|
   140|type QARunEntry = {
   141|  runId: string;
   142|  kind: string;
   143|  at: string;
   144|  ok: boolean;
   145|  summary: string;
   146|};
   147|
   148|type QAResponse = {
   149|  ok: boolean;
   150|  error?: string;
   151|  marker?: string;
   152|  schedulerRunning?: boolean;
   153|  cadence?: { healthMinutes?: number; authMinutes?: number; matrixHours?: number };
   154|  lastHealthAt?: string | null;
   155|  lastAuthAt?: string | null;
   156|  lastMatrixAt?: string | null;
   157|  healthOk?: boolean | null;
   158|  authOk?: boolean | null;
   159|  totalRuns?: number;
   160|  recentRuns?: QARunEntry[];
   161|};
   162|
   163|type CredentialRow = {
   164|  service: string;
   165|  variable: string;
   166|  environment: string;
   167|  stored: boolean;
   168|  injected: boolean;
   169|  authenticated: boolean | null;
   170|  permissionTest: string;
   171|  runtimeTest: string;
   172|  httpStatus: number | null;
   173|  securityCheck: string;
   174|  blocker: string | null;
   175|  worker: string;
   176|  finalStatus: string;
   177|  testedAt: string;
   178|};
   179|
   180|type CredentialsResponse = {
   181|  ok: boolean;
   182|  error?: string;
   183|  marker?: string;
   184|  generatedAt?: string;
   185|  totalRuns?: number;
   186|  totals?: { total: number; verified: number; partial: number; blocked: number };
   187|  credentials?: CredentialRow[];
   188|};
   189|
   190|type LedgerResponse = {
   191|  ok: boolean;
   192|  error?: string;
   193|  marker?: string;
   194|  generatedAt?: string;
   195|  version?: number;
   196|  updatedAt?: string;
   197|  counts?: LedgerCounts;
   198|  workers?: LedgerWorker[];
   199|  jobs?: LedgerJob[];
   200|  approvals?: LedgerApproval[];
   201|};
   202|
   203|const STATUS_COLORS: Record<string, string> = {
   204|  VERIFIED: '#34D399',
   205|  DONE: '#34D399',
   206|  RUNNING: '#FBBF24',
   207|  QUEUED: '#94A3B8',
   208|  BLOCKED: '#F87171',
   209|  OWNER_ACTION_REQUIRED: '#F97316',
   210|};
   211|
   212|const STATUS_ORDER: string[] = ['RUNNING', 'BLOCKED', 'OWNER_ACTION_REQUIRED', 'QUEUED', 'VERIFIED', 'DONE'];
   213|
   214|function statusColor(status: string): string {
   215|  return STATUS_COLORS[status] ?? '#94A3B8';
   216|}
   217|
   218|function formatTime(iso: string | null | undefined): string {
   219|  if (!iso) return '—';
   220|  try {
   221|    const d = new Date(iso);
   222|    return `${d.toISOString().slice(0, 10)} ${d.toISOString().slice(11, 16)} UTC`;
   223|  } catch {
   224|    return iso;
   225|  }
   226|}
   227|
   228|export default function AutonomousDashboardScreen() {
   229|  const router = useRouter();
   230|  const [data, setData] = useState<LedgerResponse | null>(null);
   231|  const [isLoading, setIsLoading] = useState<boolean>(true);
   232|  const [isRefreshing, setIsRefreshing] = useState<boolean>(false);
   233|  const [errorMessage, setErrorMessage] = useState<string | null>(null);
   234|  const [isUnauthorized, setIsUnauthorized] = useState<boolean>(false);
   235|  const [expandedJobId, setExpandedJobId] = useState<string | null>(null);
   236|  const [lastFetchedAt, setLastFetchedAt] = useState<string | null>(null);
   237|  const [guardian, setGuardian] = useState<GuardianResponse | null>(null);
   238|  const [qa, setQa] = useState<QAResponse | null>(null);
   239|  const [creds, setCreds] = useState<CredentialsResponse | null>(null);
   240|  const pollRef = useRef<ReturnType<typeof setInterval> | null>(null);
   241|
   242|  const fetchLedger = useCallback(async (silent: boolean) => {
   243|    if (!silent) setIsLoading(true);
   244|    setErrorMessage(null);
   245|    try {
   246|      const token = await getIVXAccessToken();
   247|      if (!token) {
   248|        setIsUnauthorized(true);
   249|        setErrorMessage('Owner session required. Sign in as the owner to view the autonomous ledger.');
   250|        return;
   251|      }
   252|      const response = await fetch(LEDGER_URL, {
   253|        method: 'GET',
   254|        headers: { Authorization: `Bearer ${token}` },
   255|      });
   256|      if (response.status === 401 || response.status === 403) {
   257|        setIsUnauthorized(true);
   258|        setErrorMessage('Access denied: this dashboard is restricted to the IVX owner.');
   259|        return;
   260|      }
   261|      const json = (await response.json()) as LedgerResponse;
   262|      if (!json.ok) {
   263|        setErrorMessage(json.error ?? `Ledger request failed (HTTP ${response.status}).`);
   264|        return;
   265|      }
   266|      setIsUnauthorized(false);
   267|      setData(json);
   268|      setLastFetchedAt(new Date().toISOString());
   269|      try {
   270|        const [guardianResponse, qaResponse, credsResponse] = await Promise.all([
   271|          fetch(GUARDIAN_URL, { method: 'GET', headers: { Authorization: `Bearer ${token}` } }),
   272|          fetch(QA_URL, { method: 'GET', headers: { Authorization: `Bearer ${token}` } }),
   273|          fetch(CREDENTIALS_URL, { method: 'GET', headers: { Authorization: `Bearer ${token}` } }),
   274|        ]);
   275|        if (guardianResponse.ok) {
   276|          const guardianJson = (await guardianResponse.json()) as GuardianResponse;
   277|          if (guardianJson.ok) setGuardian(guardianJson);
   278|        }
   279|        if (qaResponse.ok) {
   280|          const qaJson = (await qaResponse.json()) as QAResponse;
   281|          if (qaJson.ok) setQa(qaJson);
   282|        }
   283|        if (credsResponse.ok) {
   284|          const credsJson = (await credsResponse.json()) as CredentialsResponse;
   285|          if (credsJson.ok) setCreds(credsJson);
   286|        }
   287|      } catch (guardianError) {
   288|        console.log('[AutonomousDashboard] guardian/qa fetch skipped:', guardianError instanceof Error ? guardianError.message : guardianError);
   289|      }
   290|    } catch (err) {
   291|      const message = err instanceof Error ? err.message : 'Network error loading ledger.';
   292|      console.log('[AutonomousDashboard] fetch failed:', message);
   293|      setErrorMessage(message);
   294|    } finally {
   295|      setIsLoading(false);
   296|      setIsRefreshing(false);
   297|    }
   298|  }, []);
   299|
   300|  useEffect(() => {
   301|    fetchLedger(false);
   302|    pollRef.current = setInterval(() => fetchLedger(true), POLL_INTERVAL_MS);
   303|    return () => {
   304|      if (pollRef.current) clearInterval(pollRef.current);
   305|    };
   306|  }, [fetchLedger]);
   307|
   308|  const onRefresh = useCallback(() => {
   309|    setIsRefreshing(true);
   310|    fetchLedger(true);
   311|  }, [fetchLedger]);
   312|
   313|  const counts = data?.counts;
   314|  const jobs = data?.jobs ?? [];
   315|  const workers = data?.workers ?? [];
   316|  const approvals = (data?.approvals ?? []).filter((a) => a.status === 'PENDING');
   317|  const sortedJobs = [...jobs].sort((a, b) => {
   318|    const sa = STATUS_ORDER.indexOf(a.status);
   319|    const sb = STATUS_ORDER.indexOf(b.status);
   320|    if (sa !== sb) return sa - sb;
   321|    return a.jobId.localeCompare(b.jobId);
   322|  });
   323|  const completionPercent = counts && counts.jobs > 0 ? Math.round((counts.verified / counts.jobs) * 100) : 0;
   324|
   325|  return (
   326|    <SafeAreaView style={styles.safeArea} edges={['top', 'bottom']}>
   327|      <Stack.Screen options={{ headerShown: false }} />
   328|      <View style={styles.header}>
   329|        <TouchableOpacity onPress={() => router.back()} style={styles.backButton} testID="autonomous-dashboard-back">
   330|          <ArrowLeft size={22} color="#E2E8F0" />
   331|        </TouchableOpacity>
   332|        <View style={styles.headerTitleWrap}>
   333|          <Text style={styles.headerTitle}>Autonomous Dashboard</Text>
   334|          <Text style={styles.headerSubtitle}>
   335|            Live ledger · v{data?.version ?? '—'} · {formatTime(lastFetchedAt)}
   336|          </Text>
   337|        </View>
   338|        <TouchableOpacity onPress={onRefresh} style={styles.refreshButton} testID="autonomous-dashboard-refresh">
   339|          <RefreshCw size={18} color="#FBBF24" />
   340|        </TouchableOpacity>
   341|      </View>
   342|
   343|      {isLoading ? (
   344|        <View style={styles.centerFill}>
   345|          <ActivityIndicator size="large" color="#FBBF24" />
   346|          <Text style={styles.loadingText}>Loading live job ledger…</Text>
   347|        </View>
   348|      ) : isUnauthorized ? (
   349|        <View style={styles.centerFill}>
   350|          <Lock size={40} color="#F87171" />
   351|          <Text style={styles.errorTitle}>Owner access required</Text>
   352|          <Text style={styles.errorBody}>{errorMessage}</Text>
   353|        </View>
   354|      ) : errorMessage && !data ? (
   355|        <View style={styles.centerFill}>
   356|          <AlertTriangle size={40} color="#F87171" />
   357|          <Text style={styles.errorTitle}>Could not load ledger</Text>
   358|          <Text style={styles.errorBody}>{errorMessage}</Text>
   359|          <TouchableOpacity style={styles.retryButton} onPress={() => fetchLedger(false)}>
   360|            <Text style={styles.retryText}>Retry</Text>
   361|          </TouchableOpacity>
   362|        </View>
   363|      ) : (
   364|        <ScrollView
   365|          style={styles.scroll}
   366|          contentContainerStyle={styles.scrollContent}
   367|          refreshControl={<RefreshControl refreshing={isRefreshing} onRefresh={onRefresh} tintColor="#FBBF24" />}
   368|        >
   369|          {counts ? (
   370|            <View style={styles.card}>
   371|              <View style={styles.cardHeaderRow}>
   372|                <Activity size={16} color="#FBBF24" />
   373|                <Text style={styles.cardHeader}>Overview</Text>
   374|              </View>
   375|              <View style={styles.progressTrack}>
   376|                <View style={[styles.progressFill, { width: `${completionPercent}%` }]} />
   377|              </View>
   378|              <Text style={styles.progressLabel}>{completionPercent}% verified ({counts.verified}/{counts.jobs} jobs)</Text>
   379|              <View style={styles.statGrid}>
   380|                <StatPill label="Running" value={counts.running} color="#FBBF24" />
   381|                <StatPill label="Blocked" value={counts.blocked} color="#F87171" />
   382|                <StatPill label="Owner action" value={counts.ownerActionRequired} color="#F97316" />
   383|                <StatPill label="Queued" value={counts.queued} color="#94A3B8" />
   384|                <StatPill label="Workers" value={counts.workers} color="#60A5FA" />
   385|                <StatPill label="Approvals" value={counts.pendingApprovals} color="#F97316" />
   386|              </View>
   387|            </View>
   388|          ) : null}
   389|
   390|          {approvals.length > 0 ? (
   391|            <View style={styles.card}>
   392|              <View style={styles.cardHeaderRow}>
   393|                <ShieldCheck size={16} color="#F97316" />
   394|                <Text style={styles.cardHeader}>Approvals waiting ({approvals.length})</Text>
   395|              </View>
   396|              {approvals.map((approval) => (
   397|                <View key={approval.approvalId} style={styles.approvalRow}>
   398|                  <Text style={styles.approvalTitle}>{approval.approvalId} · {approval.title}</Text>
   399|                  <Text style={styles.approvalMeta}>Risk: {approval.risk}</Text>
   400|                  <Text style={styles.approvalMeta}>Rollback: {approval.rollback}</Text>
   401|                </View>
   402|              ))}
   403|            </View>
   404|          ) : null}
   405|
   406|          {guardian ? (
   407|            <View style={styles.card}>
   408|              <View style={styles.cardHeaderRow}>
   409|                <ShieldCheck size={16} color={guardian.overall === 'HEALTHY' ? '#34D399' : '#F87171'} />
   410|                <Text style={styles.cardHeader}>Owner Authentication</Text>
   411|                <Text style={[styles.guardianBadge, { color: guardian.overall === 'HEALTHY' ? '#34D399' : '#F87171' }]}>
   412|                  {guardian.overall ?? '—'}
   413|                </Text>
   414|              </View>
   415|              <Text style={styles.guardianMeta}>
   416|                Auth Guardian · run #{guardian.totalRuns ?? 0} · {formatTime(guardian.generatedAt)}
   417|              </Text>
   418|              {(guardian.probes ?? []).map((probe) => (
   419|                <View key={probe.id} style={styles.probeRow}>
   420|                  <View style={[styles.statusDot, { backgroundColor: probe.ok ? '#34D399' : '#F87171' }]} />
   421|                  <View style={styles.probeTextWrap}>
   422|                    <Text style={styles.probeName}>{probe.name}</Text>
   423|                    <Text style={styles.probeDetail}>
   424|                      HTTP {probe.httpStatus ?? '—'} · {probe.latencyMs}ms · {probe.detail}
   425|                    </Text>
   426|                  </View>
   427|                </View>
   428|              ))}
   429|              {(guardian.openIncidents ?? []).length > 0 ? (
   430|                <View style={styles.incidentBox}>
   431|                  <Text style={styles.incidentHeader}>Open incidents</Text>
   432|                  {(guardian.openIncidents ?? []).map((incident) => (
   433|                    <Text key={incident.incidentId} style={styles.jobBlocker}>
   434|                      {incident.incidentId} · {incident.detail} · opened {formatTime(incident.openedAt)}
   435|                    </Text>
   436|                  ))}
   437|                </View>
   438|              ) : (
   439|                <Text style={styles.jobEvidence}>No open authentication incidents.</Text>
   440|              )}
   441|              <View style={styles.smsBox}>
   442|                <Text style={styles.smsHeader}>
   443|                  SMS alerts ({guardian.smsProvider?.provider ?? 'aws_sns'}) — {guardian.smsProvider?.ready ? 'READY' : 'NOT READY'}
   444|                </Text>
   445|                <Text style={styles.probeDetail}>
   446|                  AWS creds: {guardian.smsProvider?.awsCredentialsConfigured ? 'configured' : 'MISSING on backend'} · phone: {guardian.smsProvider?.ownerPhoneMasked ?? '—'} ({guardian.smsProvider?.phoneSource ?? '—'})
   447|                </Text>
   448|                {(guardian.recentAlerts ?? []).slice(0, 3).map((alert) => (
   449|                  <Text key={alert.alertId} style={styles.probeDetail}>
   450|                    {alert.alertId} · {alert.severity} · {alert.smsStatus}
   451|                    {alert.messageId ? ` · id ${alert.messageId.slice(0, 8)}…` : ''} · {formatTime(alert.sentAt)}
   452|                  </Text>
   453|                ))}
   454|              </View>
   455|            </View>
   456|          ) : null}
   457|
   458|          {qa ? (
   459|            <View style={styles.card}>
   460|              <View style={styles.cardHeaderRow}>
   461|                <Activity size={16} color={qa.schedulerRunning ? '#34D399' : '#F87171'} />
   462|                <Text style={styles.cardHeader}>Continuous QA</Text>
   463|                <Text style={[styles.guardianBadge, { color: qa.schedulerRunning ? '#34D399' : '#F87171' }]}>
   464|                  {qa.schedulerRunning ? 'RUNNING 24/7' : 'STOPPED'}
   465|                </Text>
   466|              </View>
   467|              <Text style={styles.guardianMeta}>
   468|                Health every {qa.cadence?.healthMinutes ?? 5}m · auth every {qa.cadence?.authMinutes ?? 15}m · full matrix every {qa.cadence?.matrixHours ?? 2}h · {qa.totalRuns ?? 0} runs
   469|              </Text>
   470|              <View style={styles.qaStatusRow}>
   471|                <View style={styles.qaStatusItem}>
   472|                  <View style={[styles.statusDot, { backgroundColor: qa.healthOk === false ? '#F87171' : qa.healthOk ? '#34D399' : '#64748B' }]} />
   473|                  <Text style={styles.probeDetail}>Health {formatTime(qa.lastHealthAt)}</Text>
   474|                </View>
   475|                <View style={styles.qaStatusItem}>
   476|                  <View style={[styles.statusDot, { backgroundColor: qa.authOk === false ? '#F87171' : qa.authOk ? '#34D399' : '#64748B' }]} />
   477|                  <Text style={styles.probeDetail}>Auth matrix {formatTime(qa.lastMatrixAt)}</Text>
   478|                </View>
   479|              </View>
   480|              {(qa.recentRuns ?? []).slice(0, 6).map((run) => (
   481|                <View key={run.runId} style={styles.probeRow}>
   482|                  <View style={[styles.statusDot, { backgroundColor: run.ok ? '#34D399' : '#F87171' }]} />
   483|                  <View style={styles.probeTextWrap}>
   484|                    <Text style={styles.probeName}>{run.runId} · {run.kind}</Text>
   485|                    <Text style={styles.probeDetail}>{formatTime(run.at)} · {run.summary}</Text>
   486|                  </View>
   487|                </View>
   488|              ))}
   489|            </View>
   490|          ) : null}
   491|
   492|          {creds ? (
   493|            <View style={styles.card}>
   494|              <View style={styles.cardHeaderRow}>
   495|                <Lock size={16} color={creds.totals && creds.totals.blocked > 0 ? '#F97316' : '#34D399'} />
   496|                <Text style={styles.cardHeader}>Credentials &amp; Integrations</Text>
   497|                <Text style={[styles.guardianBadge, { color: creds.totals && creds.totals.blocked > 0 ? '#F97316' : '#34D399' }]}>
   498|                  {creds.totals ? `${creds.totals.verified}/${creds.totals.total} VERIFIED` : '—'}
   499|                </Text>
   500|              </View>
   501|              <Text style={styles.guardianMeta}>
   502|                Live binding tests · run #{creds.totalRuns ?? 0} · {formatTime(creds.generatedAt)} · no secret values shown
   503|              </Text>
   504|              {(creds.credentials ?? []).map((row) => (
   505|                <View key={`${row.service}-${row.variable}`} style={styles.probeRow}>
   506|                  <View
   507|                    style={[styles.statusDot, {
   508|                      backgroundColor:
   509|                        row.finalStatus === 'VERIFIED' ? '#34D399' : row.finalStatus === 'PARTIAL' ? '#FBBF24' : '#F87171',
   510|                    }]}
   511|                  />
   512|                  <View style={styles.probeTextWrap}>
   513|                    <Text style={styles.probeName}>{row.service} · {row.finalStatus} · {row.worker}</Text>
   514|                    <Text style={styles.probeDetail}>{row.variable} · {row.environment} · stored {row.stored ? 'yes' : 'NO'} · injected {row.injected ? 'yes' : 'NO'}</Text>
   515|                    <Text style={styles.probeDetail}>{row.runtimeTest}</Text>
   516|                    <Text style={styles.probeDetail}>{row.permissionTest}</Text>
   517|                    {row.blocker ? <Text style={styles.jobBlocker}>Blocker: {row.blocker}</Text> : null}
   518|                  </View>
   519|                </View>
