input.command:
cd /home/user/rork-app && TOKEN=$(cat /tmp/owner_token.txt); echo "=== Live engine runs from executive-layer ==="; curl -s -H "Authorization: Bearer $TOKEN" "https://api.ivxholding.com/api/ivx/executive-layer" 2>&1 | node -e "
const data = [];
process.stdin.on('data', chunk => data.push(chunk));
process.stdin.on('end', () => {
  try {
    const r = JSON.parse(Buffer.concat(data).toString());
    const a = r.executive?.autonomousActions;
    if (!a) { console.log('No autonomousActions'); return; }
    console.log('schedulerEnabled:', a.schedulerEnabled);
    console.log('totalRuns:', a.totalRuns);
    console.log('runsWithEvidence:', a.runsWithEvidence);
    console.log('runsWithoutEvidence:', a.runsWithoutEvidence);
    console.log('actions:');
    (a.actions||[]).forEach(act => {
      console.log('  ' + act.kind + ' | ' + act.status + ' | runs=' + act.runCount + ' | last=' + act.lastRunAt + ' | ' + act.summary);
    });
  } catch(e) { console.log('parse error:', e.message); }
});
" 2>&1

