input.command:
cd /home/user/rork-app && TOKEN=$(cat /tmp/owner_token.txt); echo "=== Full ledger data ==="; curl -s -H "Authorization: Bearer $TOKEN" "https://api.ivxholding.com/api/ivx/autonomous/ledger" 2>&1 | node -e "
const data = [];
process.stdin.on('data', chunk => data.push(chunk));
process.stdin.on('end', () => {
  try {
    const r = JSON.parse(Buffer.concat(data).toString());
    console.log('ok:', r.ok, '| version:', r.version, '| marker:', r.marker);
    console.log('generatedAt:', r.generatedAt);
    console.log('counts:', JSON.stringify(r.counts));
    console.log('workers:', (r.workers||[]).length);
    console.log('jobs:', (r.jobs||[]).length);
    const jobs = r.jobs || [];
    const running = jobs.filter(j => j.status === 'RUNNING');
    const verified = jobs.filter(j => j.status === 'VERIFIED' || j.status === 'DONE');
    const blocked = jobs.filter(j => j.status === 'BLOCKED');
    const queued = jobs.filter(j => j.status === 'QUEUED');
    const ownerAction = jobs.filter(j => j.status === 'OWNER_ACTION_REQUIRED');
    console.log('running:', running.length, 'verified:', verified.length, 'blocked:', blocked.length, 'queued:', queued.length, 'ownerAction:', ownerAction.length);
    console.log('latest updatedAt:', jobs.map(j=>j.updatedAt).sort().reverse()[0]);
  } catch(e) { console.log('parse error:', e.message); }
});
" 2>&1

