cd /home/user/rork-app && TOKEN=$(cat /tmp/owner_token.txt); echo "=== Auth guardian probes ==="; curl -s -H "Authorization: Bearer $TOKEN" "https://api.ivxholding.com/api/ivx/autonomous/auth-guardian" 2>&1 | node -e "
const d=[];process.stdin.on('data',c=>d.push(c));process.stdin.on('end',()=>{
  try{const r=JSON.parse(Buffer.concat(d).toString());
    console.log('overall:', r.overall, '| totalRuns:', r.totalRuns, '| incidents:', (r.openIncidents||[]).length);
    (r.probes||[]).forEach(p=>console.log('  '+p.id+' | ok='+p.ok+' | HTTP='+p.httpStatus+' | '+p.latencyMs+'ms | '+p.detail));
  }catch(e){console.log('err',e.message)}
});
" 2>&1

